/// The `SessionWebService`.
///
/// This service provides functionallity that is related to the
/// current session of the webservice.
#[derive(Debug, Clone, Copy)]
pub struct SessionService<'a> {
    client: &'a Client,
}

impl Client {
    /// The `SessionWebService`.
    pub fn session(&self) -> SessionService<'_> {
        SessionService { client: self }
    }
}

impl SessionService<'_> {
    /// Starts a explicit transaction for the current session.
    /// Usually transactions are started and committed for each call to the webservice, but if a transaction has been started explicitly it also has to be terminated using endTransaction.
    ///
    /// `SessionWebService.beginTransaction` (modifies data; refused by read-only clients)
    pub async fn begin_transaction(&self) -> Result<()> {
        let mut w = XmlWriter::new();
        w.open("sessioni", "beginTransaction");
        w.open_end();
        w.close("sessioni", "beginTransaction");
        self.client
            .call(
                "SessionWebService",
                "beginTransaction",
                false,
                w.into_string(),
                |_| Ok(()),
            )
            .await
    }

    /// Terminates the current session.
    ///
    /// `SessionWebService.endSession`
    pub async fn end_session(&self) -> Result<()> {
        let mut w = XmlWriter::new();
        w.open("sessioni", "endSession");
        w.open_end();
        w.close("sessioni", "endSession");
        self.client
            .call(
                "SessionWebService",
                "endSession",
                true,
                w.into_string(),
                |_| Ok(()),
            )
            .await
    }

    /// Ends the explicit transaction of the current session by either commit or rollback.
    /// - `rollback`: if true the transaction is rolled back otherwise it is commited.
    ///
    /// `SessionWebService.endTransaction` (modifies data; refused by read-only clients)
    pub async fn end_transaction(&self, rollback: bool) -> Result<()> {
        let mut w = XmlWriter::new();
        w.open("sessioni", "endTransaction");
        w.open_end();
        rollback.write_xml(&mut w, "sessioni", "rollback");
        w.close("sessioni", "endTransaction");
        self.client
            .call(
                "SessionWebService",
                "endTransaction",
                false,
                w.into_string(),
                |_| Ok(()),
            )
            .await
    }

    /// Checks if a user is logged in for the current session.
    ///
    /// `SessionWebService.hasSubject`
    pub async fn has_subject(&self) -> Result<bool> {
        let mut w = XmlWriter::new();
        w.open("sessioni", "hasSubject");
        w.open_end();
        w.close("sessioni", "hasSubject");
        self.client
            .call(
                "SessionWebService",
                "hasSubject",
                true,
                w.into_string(),
                |node| match node
                    .children()
                    .find(|c| c.is_element() && c.tag_name().name() == "hasSubjectReturn")
                {
                    Some(c) => xml::read_req(c),
                    None => Err(Error::Decode {
                        element: "hasSubjectResponse".into(),
                        message: "missing hasSubjectReturn".into(),
                    }),
                },
            )
            .await
    }

    /// Logs a user in for the current session.
    /// - `userName`: the name of the user to log-in.
    /// - `password`: the password of the user to log-in.
    ///
    /// `SessionWebService.logIn`
    pub async fn log_in(&self, user_name: &str, password: &str) -> Result<()> {
        let mut w = XmlWriter::new();
        w.open("sessioni", "logIn");
        w.open_end();
        user_name.write_xml(&mut w, "sessioni", "userName");
        password.write_xml(&mut w, "sessioni", "password");
        w.close("sessioni", "logIn");
        self.client
            .call("SessionWebService", "logIn", true, w.into_string(), |_| {
                Ok(())
            })
            .await
    }

    /// This method works for both Teamcenter Security Services SSO and Personal Access Tokens (since Polarion 3.22.1).
    /// Possible (case insensitive) values for the mechanism parameters: TcSS and AccessToken.
    ///
    /// This will NOT work for the other SSO methods supported by Polarion. (Kerberos, SAML, or OAuth2.)
    /// For SAML, OAuth2 (or deprecated Kerberos), you should use the SessionWebService.logIn(username, password) method (LDAP configuration should be enabled for web services) or use an access token.
    ///
    /// - `mechanism`: the mechanism that the client requests for authentication. If the TcSS mechanism is used, the server must be configured for TcSS. (Otherwise, the login with this mechanism will be rejected.) AccessToken is always accepted.
    /// - `username`: the name of the user to login. Required for TcSS. null for AccessToken
    /// - `token`: the token of the user to login.
    /// - Since Polarion 3.17.0
    ///
    /// `SessionWebService.logInWithToken`
    pub async fn log_in_with_token(
        &self,
        mechanism: &str,
        username: &str,
        token: &str,
    ) -> Result<()> {
        let mut w = XmlWriter::new();
        w.open("sessioni", "logInWithToken");
        w.open_end();
        mechanism.write_xml(&mut w, "sessioni", "mechanism");
        username.write_xml(&mut w, "sessioni", "username");
        token.write_xml(&mut w, "sessioni", "token");
        w.close("sessioni", "logInWithToken");
        self.client
            .call(
                "SessionWebService",
                "logInWithToken",
                true,
                w.into_string(),
                |_| Ok(()),
            )
            .await
    }

    /// Check if there is a explicit transaction (started with beginTransaction) for the current session.
    ///
    /// `SessionWebService.transactionExists`
    pub async fn transaction_exists(&self) -> Result<bool> {
        let mut w = XmlWriter::new();
        w.open("sessioni", "transactionExists");
        w.open_end();
        w.close("sessioni", "transactionExists");
        self.client
            .call(
                "SessionWebService",
                "transactionExists",
                true,
                w.into_string(),
                |node| match node
                    .children()
                    .find(|c| c.is_element() && c.tag_name().name() == "transactionExistsReturn")
                {
                    Some(c) => xml::read_req(c),
                    None => Err(Error::Decode {
                        element: "transactionExistsResponse".into(),
                        message: "missing transactionExistsReturn".into(),
                    }),
                },
            )
            .await
    }
}

