        test_result_id.write_xml(&mut w, "testmanagementi", "testResultId");
        test_comment.write_xml(&mut w, "testmanagementi", "testComment");
        executed_by_uri.write_xml(&mut w, "testmanagementi", "executedByUri");
        executed.write_xml(&mut w, "testmanagementi", "executed");
        duration.write_xml(&mut w, "testmanagementi", "duration");
        defect_uri.write_xml(&mut w, "testmanagementi", "defectUri");
        w.close("testmanagementi", "updateTestRecord");
        self.client
