    /// Moves a Work Item to a specific position in a Document.
    /// If the Work Item is not yet inside the Document it will be moved into the Document.
    /// Modules are also supported.
    /// - `workItemURI`: The URI of the Work Item to be moved.
    /// - `documentURI`: The URI of the Document.
    /// - `parentWorkItemURI`: The URI of the parent Work Item or `null` to insert it as the root.
    /// - `position`: The desired position in the list of children or a value \< 0 to insert the Work Item at the end.
    /// (If the old and new parent are the same, then the moved Work Item is not counted.)
    /// - `retainDocumentFlow`: `true` to retain the position of the moved Work Item in the document flow, even if it means changing the parent.
    /// `false` to keep the desired parent, even if it means moving the Work Item to a different position.
    /// - Since Polarion 3.7.0
    ///
    /// `TrackerWebService.moveWorkItemToDocument` (modifies data; refused by read-only clients)
    pub async fn move_work_item_to_document(
        &self,
        work_item_uri: &str,
        document_uri: &str,
        parent_work_item_uri: Option<&str>,
        position: i32,
        retain_document_flow: bool,
    ) -> Result<()> {
        let mut w = XmlWriter::new();
        w.open("trackeri", "moveWorkItemToDocument");
        w.open_end();
        work_item_uri.write_xml(&mut w, "trackeri", "workItemURI");
        document_uri.write_xml(&mut w, "trackeri", "documentURI");
        match parent_work_item_uri {
            Some(v) => {
                v.write_xml(&mut w, "trackeri", "parentWorkItemURI");
            }
            None => w.nil("trackeri", "parentWorkItemURI"),
        }
        position.write_xml(&mut w, "trackeri", "position");
        retain_document_flow.write_xml(&mut w, "trackeri", "retainDocumentFlow");
        w.close("trackeri", "moveWorkItemToDocument");
        self.client
            .call(
                "TrackerWebService",
                "moveWorkItemToDocument",
                false,
                w.into_string(),
                |_| Ok(()),
            )
            .await
    }

    /// Moves a Work Item to a specific position in a Module/Document.
    /// If the Work Item is not yet inside the Module/Document it will be moved there.
    /// Since 3.7.0 this no longer retains the document flow, but keeps the desired parent.
    /// - `workItemURI`: The URI of the Work Item to be moved.
    /// - `moduleURI`: The URI of the Module/Document.
    /// - `parentWorkItemURI`: The URI of the parent Work Item or `null` to insert it as the root.
    /// - `position`: The desired position in the list of children or a value \< 0 to insert at the end.
    /// (If the old and new parent are the same, then the moved Work Item is not counted.)
    /// - **Deprecated** Use `#moveWorkItemToDocument(String, String, String, int, boolean)`.
