    /// Creates a new Document based on an existing Document.
    /// - `sourceURI`: The URI of the source Document. (Not null.)
    /// - `targetProjectId`: The target Project Id. (Not null.)
    /// - `targetLocation`: The document's Space location with one component or null for the default space. (Can be null.)
    /// - `targetName`: The target Document's name. (Not null.)
    /// - `targetTitle`: The target Document's title. (Can be null.)
    /// - `updateTitleInDocument`: if true then the first title found in the document will be changed to the targetTitle value. (If permissions allow it).
    /// - `linkRole`: The role of links going from a reused Work Item to its source Work Item or null to not create links unless the
    /// derivedFields are specified. If this is the case, the links will be created with the default role.  (Can be null.)
    /// - `derivedFields`: The fields that are derived from the source Document. (See updateDerivedModule.) (Can be null.)
    /// - Returns: The URI of the created Document.
    /// - Since Polarion 3.8.2
    ///
    /// `TrackerWebService.reuseDocument` (modifies data; refused by read-only clients)
    pub async fn reuse_document(
        &self,
        source_uri: &str,
        target_project_id: &str,
        target_location: Option<&str>,
        target_name: &str,
        target_title: Option<&str>,
        update_title_in_document: bool,
        link_role: Option<&EnumOptionId>,
        derived_fields: &[String],
    ) -> Result<String> {
        let mut w = XmlWriter::new();
        w.open("trackeri", "reuseDocument");
        w.open_end();
        source_uri.write_xml(&mut w, "trackeri", "sourceURI");
        target_project_id.write_xml(&mut w, "trackeri", "targetProjectId");
        match target_location {
            Some(v) => {
                v.write_xml(&mut w, "trackeri", "targetLocation");
            }
            None => w.nil("trackeri", "targetLocation"),
        }
        target_name.write_xml(&mut w, "trackeri", "targetName");
        match target_title {
            Some(v) => {
                v.write_xml(&mut w, "trackeri", "targetTitle");
            }
            None => w.nil("trackeri", "targetTitle"),
        }
        update_title_in_document.write_xml(&mut w, "trackeri", "updateTitleInDocument");
        match link_role {
            Some(v) => {
                v.write_xml(&mut w, "trackeri", "linkRole");
            }
            None => w.nil("trackeri", "linkRole"),
        }
        for v in derived_fields {
            v.write_xml(&mut w, "trackeri", "derivedFields");
        }
        w.close("trackeri", "reuseDocument");
        self.client
            .call(
                "TrackerWebService",
                "reuseDocument",
                false,
                w.into_string(),
                |node| match node
                    .children()
                    .find(|c| c.is_element() && c.tag_name().name() == "reuseDocumentReturn")
                {
                    Some(c) => xml::read_req(c),
                    None => Err(Error::Decode {
                        element: "reuseDocumentResponse".into(),
                        message: "missing reuseDocumentReturn".into(),
                    }),
                },
            )
            .await
    }

